"""Append results to docs/paper_review_round1_analyses.md below the pre-specification (baa47ab); text above the closing '---' line is not changed.
Usage: python rv_render.py RESULTS_COMMIT. Inputs: results/paper_final/review_round1/*.json (r13_abmil.json optional)."""
import json, sys, os
RC = sys.argv[1]; R = "results/paper_final/review_round1"; DOC = "docs/paper_review_round1_analyses.md"; J = lambda f: json.load(open(f"{R}/{f}.json"))
f3 = lambda x: "—" if x is None else f"{x:.3f}"; ci = lambda c: "" if not c or c[0] is None else f" [{c[0]:.3f}, {c[1]:.3f}]"; sg = lambda x: f"{x:+.3f}"; cis = lambda c: f" [{c[0]:+.3f}, {c[1]:+.3f}]"
doc = open(DOC).read(); head = doc[: doc.rindex("\n---")].rstrip("\n") + "\n\n---\n"
L = ["", "## Results", "", f"Pre-specification commit baa47ab; results commit {RC}. Script `scripts/paper_plan/rv_round1.py` (Slurm via `scripts/cluster/campaign.sh`, prefix rv; R13 prefix rva), `rv_render.py`. Aggregates `results/paper_final/review_round1/`.", ""]
r13 = os.path.exists(f"{R}/r13_abmil.json")
L += ["### Status", "", "| Item | Status |", "|---|---|"] + [f"| {k} | DONE |" for k in ("R1 matched-specificity comparators", "R2 patient-level discrimination", "R3 calibration", "R4 scanner like-for-like and transfer triage", "R5 confounders", "R6 timing", "R7 worst grade to date", "R8 no-vote triage", "R9 score correlation", "R10 C-index without within-patient pairs", "R11 proportional hazards", "R12 band predictive values")] + [f"| R13 attention MIL under 10 × 10 CV | {'DONE' if r13 else 'PENDING'} |", ""]
L += ["### R1. Matched specificity (fold-honest; secondary test-set matching in the last column)", "", "| Population | Triage sens / spec | Comparator | Comparator sens / spec | Δ sens triage − comparator [95% CI] | Δ spec [95% CI] | Secondary Δ sens [95% CI] |", "|---|---|---|---|---|---|---|"]
for t, lab in (("r1_their_pre", "their, all pre-event"), ("r1_their_pre_ndbe", "their, NDBE pre-event"), ("r1_pkg_pre", "package, all pre-event"), ("r1_pkg_pre_ndbe", "package, NDBE pre-event")):
    x = J(t)["R1"]
    for a, v in x["matched"].items():
        s = x["secondary_test_set_matching"][a]["d_sens_triage_minus"]
        L.append(f"| {lab} | {f3(x['triage']['sensitivity'])} / {f3(x['triage']['specificity'])} | {a} ({v['model']}) | {f3(v['sensitivity'])} / {f3(v['specificity'])} | {sg(v['d_sens_triage_minus']['delta'])}{cis(v['d_sens_triage_minus']['ci95'])} | {sg(v['d_spec_triage_minus']['delta'])}{cis(v['d_spec_triage_minus']['ci95'])} | {sg(s['delta'])}{cis(s['ci95'])} |")
x = J("r1_their_pre")["R1"]; b = x["matched"]["B*"]["d_sens_triage_minus"]["ci95"]; c = x["matched"]["C*"]["d_sens_triage_minus"]["ci95"]
L += ["", f"One line (pre-specified rule): against B\\* the CI of Δ sensitivity contains 0 ({b[0]:+.3f} to {b[1]:+.3f}), so the triage matches the accuracy of sequencing everyone with late fusion while sequencing fewer samples; against C\\* the lower bound is {'above' if c[0] > 0 else 'not above'} 0 ({c[0]:+.3f}), so the triage {'adds' if c[0] > 0 else 'is not shown to add'} sensitivity over H&E alone at matched specificity (their matrix, all pre-event; the secondary test-set matching CI includes 0).", ""]
r2 = J("r2")["R2"]; L += ["### R2. Patient-level and patient-weighted discrimination (fold-stratified)", "", "| CNV source | Measure | L-CNV | L-IMG | L-LATE | P | L-IMG − L-CNV [two-sided 95% CI]; one-sided lower | L-LATE − L-CNV [95% CI] |", "|---|---|---|---|---|---|---|---|"]
for s, o in r2.items():
    for m in ("patient_mean", "patient_earliest", "patient_weighted_samples"):
        a = o[m]["auroc"]; d = o[m]["IMG_minus_CNV"]; e = o[m]["LATE_minus_CNV"]
        L.append(f"| {s} | {m.replace('_', ' ')} | {f3(a['L-CNV']['value'])} | {f3(a['L-IMG']['value'])} | {f3(a['L-LATE']['value'])} | {f3(a['P']['value'])} | {sg(d['delta'])}{cis(d['ci95_two_sided'])}; {f3(d['one_sided_95_lower'])} | {sg(e['delta'])}{cis(e['ci95'])} |")
r3 = J("r3")["R3"]; L += ["", "### R3. Calibration (repeat-mean predictions; relative only, case–control)", "", "| Model | Slope [95% CI] | Intercept [95% CI] | Calibration-in-the-large [95% CI] | Mean predicted / observed |", "|---|---|---|---|---|"]
L += [f"| {m} | {f3(v['slope']['value'])}{ci(v['slope']['ci95'])} | {f3(v['intercept']['value'])}{ci(v['intercept']['ci95'])} | {f3(v['calibration_in_the_large']['value'])}{ci(v['calibration_in_the_large']['ci95'])} | {f3(v['mean_pred'])} / {f3(v['observed'])} |" for m, v in r3.items()]
r4 = J("r4")["R4"]; L += ["", "### R4. Scanner", "", "| Main CV scored on | Samples / patients | L-IMG | L-CNV | L-LATE |", "|---|---|---|---|---|"]
L += [f"| {sc} | {v['n_samples']} / {v['n_patients']} | {f3(v['L-IMG']['value'])}{ci(v['L-IMG']['ci95'])} | {f3(v['L-CNV']['value'])}{ci(v['L-CNV']['ci95'])} | {f3(v['L-LATE']['value'])}{ci(v['L-LATE']['ci95'])} |" for sc, v in r4["a_main_cv_by_scanner"].items()]
t = r4["b_transfer_triage_C13210"]; L += ["", f"Triage on C13210 ({t['n_samples']} samples, {t['n_patients']} patients, {t['n_P_patients']} progressors): under transfer (cut-offs t_low {t['cutoffs']['t_low']}, c* {t['cutoffs']['c_star']}, t_seq {t['cutoffs']['t_seq']}) sensitivity {f3(t['transfer']['sensitivity'])}{ci(t['transfer']['sens_ci95'])}, specificity {f3(t['transfer']['specificity'])}{ci(t['transfer']['spec_ci95'])}, bands low/mid/high {t['transfer']['band_shares']}; main mixed-scanner CV triage on the same samples sensitivity {f3(t['main_cv_triage_on_C13210']['sensitivity'])}{ci(t['main_cv_triage_on_C13210']['sens_ci95'])}, specificity {f3(t['main_cv_triage_on_C13210']['specificity'])}{ci(t['main_cv_triage_on_C13210']['spec_ci95'])}, bands {t['main_cv_triage_on_C13210']['band_shares_mean_over_repeats']}.", "",
      "Within-C13210 CV pairs: " + "; ".join(f"repeat {p['rep']}: {p['folds_with_both_classes']} folds, {p['within_fold_pairs']} pairs" for p in r4["c_within_C13210_pairs"]["per_repeat"]) + f" (of {r4['c_within_C13210_pairs']['all_pairs_without_folds']} case–control pairs overall).", ""]
r5 = J("r5")["R5"]; L += ["### R5. Confounders", ""] + [f"- {k}: {f3(v['value'])}{ci(v['ci95'])}" + (f" (n {v['n_samples']})" if 'n_samples' in v else "") + (f" (unadjusted {v['unadjusted']})" if 'unadjusted' in v else "") for k, v in r5.items()] + [""]
r6 = J("r6")["R6"]; te = r6["time_to_event_progressor_samples"]; ex = r6["excluding_progressor_samples_within_1y"]
L += ["### R6. Timing", "", f"Progressor pre-event samples: median {te['median']} years to event (IQR {te['iqr'][0]}–{te['iqr'][1]}); {te['n_le_0.5y']} samples ({te['patients_le_0.5y']} patients) within 6 months, {te['n_le_1y']} ({te['patients_le_1y']}) within 1 year.",
      f"Excluding those within 1 year ({ex['n_samples']} samples, {ex['n_progressor_samples']} progressor, {ex['n_patients']} patients): " + ", ".join(f"{m} {f3(v['value'])}{ci(v['ci95'])}" for m, v in ex["auroc"].items()) + f"; L-IMG − L-CNV {sg(ex['IMG_minus_CNV']['delta'])}{cis(ex['IMG_minus_CNV']['ci95'])}, one-sided lower {f3(ex['IMG_minus_CNV']['one_sided_95_lower'])}; stored-call sensitivity " + ", ".join(f"{k} {f3(v)}" for k, v in ex["sensitivity_stored_calls"].items()) + ".", ""]
r7 = J("r7")["R7"]; L += ["### R7. Worst grade to date", ""] + [f"- {p}: worst grade {f3(o['auroc']['worst_grade_to_date']['value'])}{ci(o['auroc']['worst_grade_to_date']['ci95'])}; " + ", ".join(f"{m} − worst grade {sg(v['delta'])}{cis(v['ci95'])}" for m, v in o["delta_vs_worst_grade"].items()) for p, o in r7.items()] + [""]
r8 = J("r8")["R8"]; L += ["### R8. Without the vote (mean over repeats, range)", "", "| CNV source | Strategy | Sensitivity | Specificity | Progressor patients missed | Non-progressor patients with a false positive |", "|---|---|---|---|---|---|"]
for s, o in r8.items():
    for k in ("triage_LATE", "A", "B", "C"):
        v = o[k]; L.append(f"| {s} | {k} | {f3(v['sensitivity_mean'])} ({v['sensitivity_range'][0]}–{v['sensitivity_range'][1]}) | {f3(v['specificity_mean'])} ({v['specificity_range'][0]}–{v['specificity_range'][1]}) | {v['patients_missed_mean']} ({v['patients_missed_range'][0]}–{v['patients_missed_range'][1]}) | {v['nonprog_patients_fp_mean']} ({v['nonprog_patients_fp_range'][0]}–{v['nonprog_patients_fp_range'][1]}) |")
    L.append(f"| {s} | share sequenced | {o['share_sequenced_per_repeat']['mean']} ({o['share_sequenced_per_repeat']['range'][0]}–{o['share_sequenced_per_repeat']['range'][1]}); in middle band in ≥ 1 repeat {o['share_middle_band_in_at_least_one_repeat']} | | | |")
r9 = J("r9")["R9"]; L += ["", "### R9. Spearman correlation of L-IMG and L-CNV (repeat-mean)", ""] + [f"- {s}: " + ", ".join(f"{k} {f3(v['spearman'])}{ci(v['ci95'])}" for k, v in o.items()) for s, o in r9.items()] + [""]
r10 = J("r10")["R10"]; L += ["### R10. Harrell's C without within-patient pairs", "", "; ".join(f"{k} {f3(v['harrell_excl_within_patient'])}{ci(v['ci95'])}" if "harrell_excl_within_patient" in v else f"{k} {sg(v['delta'])}{cis(v['ci95'])} (p {v['p_two_sided']})" for k, v in r10.items()) + ".", ""]
r11 = J("r11")["R11"]; L += ["### R11. Proportional hazards (Schoenfeld, rank transform)", "", "; ".join(f"{m}: moderate p {v['p_moderate']}, high p {v['p_high']}" for m, v in r11.items()) + ".", ""]
r12 = J("r12")["R12"]; L += ["### R12. Band predictive values", "", "| Prevalence | PPV high band | NPV low band | Progressor share in middle band |", "|---|---|---|---|"] + [f"| {f3(v['prevalence'])} | {f3(v['PPV_high_band']['value'])}{ci(v['PPV_high_band']['ci95'])} | {f3(v['NPV_low_band']['value'])}{ci(v['NPV_low_band']['ci95'])} | {f3(v['progressor_share_middle_band']['value'])}{ci(v['progressor_share_middle_band']['ci95'])} |" for v in r12.values()] + [""]
if r13:
    x = J("r13_abmil"); a = x["auroc"]; pr = x["paired"]
    L += ["### R13. Attention MIL under 10 × 10 CV (fold-stratified, all pre-event samples)", "", "| Model | AUROC [95% CI] |", "|---|---|"] + [f"| {m} | {f3(v['value'])}{ci(v['ci95'])} |" for m, v in a.items()]
    L += ["", "; ".join(f"{k}: {sg(v['delta'])}{cis(v['ci95'])} (p {v['p_bootstrap_unadjusted']})" for k, v in pr.items()) + ". Trained on CPU (as the stored leave-one-patient-out N-IMG runs); 0 GPU-hours. Validation group chosen as in `km_neural.py` (seed-1 shuffle of training patients, group 1 held out).", ""]
else:
    L += ["### R13. Attention MIL under 10 × 10 CV", "", "Pending (running separately; appended when complete).", ""]
L += ["### Deviations", "", "- None in method. R13 was trained on CPU rather than GPU (matching the stored leave-one-patient-out runs); this does not change the analysis.", ""]
open(DOC, "w").write(head + "\n".join(L) + "\n"); print("rendered")
